\centering
\topcaption{\label{results:tab1}
  Number of selected events from simulation and observed in data. The uncertainties are statistical.
}
\begin{tabular}{lcc}
\hline
\multirow{2}{*}{Process} & \multicolumn{2}{c}{Number of events} \\
 & Leading $\mu$ & Leading $\Pe$ \\
\hline \\[-2.2ex]
$\ttbar \to \PQb \ell^- \PAGn \PAQb\PQq\PAQq'$ & $228.1 \pm 4.0$ & $195.6 \pm 3.7$ \\
